import json
from typing import Any, Dict, Optional

from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.core.credentials import AzureKeyCredential


def _get_field_value(field: Any) -> Any:
    if field is None:
        return None
    if hasattr(field, "value"):
        return field.value
    return field


def _get_number(field: Any) -> Optional[float]:
    value = _get_field_value(field)
    if value is None:
        return None
    try:
        return float(value)
    except (TypeError, ValueError):
        return None


def _get_str(field: Any) -> Optional[str]:
    value = _get_field_value(field)
    if value is None:
        return None
    return str(value)


def normalize_invoice_fields(result: Any) -> Dict[str, Any]:
    doc = result.documents[0] if getattr(result, "documents", None) else None
    fields = getattr(doc, "fields", {}) if doc else {}

    def f(name: str) -> Any:
        return fields.get(name)

    vendor_name = _get_str(f("VendorName"))
    invoice_id = _get_str(f("InvoiceId"))
    invoice_date = _get_str(f("InvoiceDate"))
    due_date = _get_str(f("DueDate"))
    purchase_order = _get_str(f("PurchaseOrder"))
    currency = _get_str(f("InvoiceTotal").currency_code if f("InvoiceTotal") and hasattr(f("InvoiceTotal"), "currency_code") else None)

    subtotal = _get_number(f("SubTotal"))
    total_tax = _get_number(f("TotalTax"))
    invoice_total = _get_number(f("InvoiceTotal"))
    amount_due = _get_number(f("AmountDue"))

    billing_address = _get_str(f("BillingAddress"))
    shipping_address = _get_str(f("ShippingAddress"))

    items = []
    line_items = f("Items")
    if line_items and getattr(line_items, "value", None):
        for item in line_items.value:
            item_fields = getattr(item, "value", {}) if hasattr(item, "value") else {}
            items.append(
                {
                    "description": _get_str(item_fields.get("Description")),
                    "quantity": _get_number(item_fields.get("Quantity")),
                    "unit_price": _get_number(item_fields.get("UnitPrice")),
                    "amount": _get_number(item_fields.get("Amount")),
                    "product_code": _get_str(item_fields.get("ProductCode")),
                }
            )

    return {
        "vendor_name": vendor_name,
        "invoice_id": invoice_id,
        "invoice_date": invoice_date,
        "due_date": due_date,
        "purchase_order": purchase_order,
        "currency": currency,
        "subtotal": subtotal,
        "total_tax": total_tax,
        "invoice_total": invoice_total,
        "amount_due": amount_due,
        "billing_address": billing_address,
        "shipping_address": shipping_address,
        "line_items": items,
        "raw_provider": "azure-ai-documentintelligence",
    }


def extract_expense_fields(document_url: str) -> Dict[str, Any]:
    endpoint = __import__("os").environ["AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT"]
    key = __import__("os").environ["AZURE_DOCUMENT_INTELLIGENCE_KEY"]

    client = DocumentIntelligenceClient(endpoint=endpoint, credential=AzureKeyCredential(key))
    poller = client.begin_analyze_document(
        model_id="prebuilt-invoice",
        analyze_request={"urlSource": document_url},
        content_type="application/json",
    )
    result = poller.result()
    return normalize_invoice_fields(result)


def extract_expense_fields_from_bytes(document_bytes: bytes) -> Dict[str, Any]:
    endpoint = __import__("os").environ["AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT"]
    key = __import__("os").environ["AZURE_DOCUMENT_INTELLIGENCE_KEY"]

    client = DocumentIntelligenceClient(endpoint=endpoint, credential=AzureKeyCredential(key))
    poller = client.begin_analyze_document(
        model_id="prebuilt-invoice",
        body=document_bytes,
    )
    result = poller.result()
    return normalize_invoice_fields(result)
